import { Hono } from 'hono'

import { FetchImageError, fetchRemoteImage } from './lib/image-fetcher'

const app = new Hono()

const hopByHopHeaders = new Set([
  'connection',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailers',
  'transfer-encoding',
  'upgrade'
])

const createForwardHeaders = (upstream: Response): Headers => {
  const headers = new Headers()
  upstream.headers.forEach((value, key) => {
    if (hopByHopHeaders.has(key.toLowerCase())) {
      return
    }
    headers.append(key, value)
  })

  if (!headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/octet-stream')
  }

  headers.set('Cache-Control', 'public, max-age=31536000')
  return headers
}

app.get('/', async (c) => {
  const url = c.req.query('url')
  if (!url) {
    return c.json({ error: 'Missing url parameter' }, 400)
  }

  try {
    const upstream = await fetchRemoteImage(url)
    const headers = createForwardHeaders(upstream)
    return new Response(upstream.body, {
      status: upstream.status,
      statusText: upstream.statusText,
      headers
    })
  } catch (error) {
    if (error instanceof FetchImageError) {
      return c.json({ error: error.message }, error.status ?? 502)
    }
    console.error('Unexpected error fetching image', error)
    return c.json({ error: 'Unexpected error fetching image' }, 502)
  }
})

export default app

export type ImageFormat = 'jpeg' | 'png' | 'webp' | 'avif'

const MIME_TO_FORMAT: Record<string, ImageFormat> = {
  'image/jpeg': 'jpeg',
  'image/jpg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/avif': 'avif'
}

export const detectImageFormat = (buffer: Uint8Array, contentType?: string | null): ImageFormat | null => {
  if (contentType) {
    const normalised = contentType.split(';')[0]?.trim().toLowerCase()
    if (normalised && normalised in MIME_TO_FORMAT) {
      return MIME_TO_FORMAT[normalised]
    }
  }

  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return 'jpeg'
  }

  if (
    buffer.length >= 8 &&
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47 &&
    buffer[4] === 0x0d &&
    buffer[5] === 0x0a &&
    buffer[6] === 0x1a &&
    buffer[7] === 0x0a
  ) {
    return 'png'
  }

  if (
    buffer.length >= 12 &&
    buffer[0] === 0x52 && // R
    buffer[1] === 0x49 && // I
    buffer[2] === 0x46 && // F
    buffer[3] === 0x46 && // F
    buffer[8] === 0x57 && // W
    buffer[9] === 0x45 && // E
    buffer[10] === 0x42 && // B
    buffer[11] === 0x50 // P
  ) {
    return 'webp'
  }

  if (
    buffer.length >= 12 &&
    buffer[4] === 0x66 && // f
    buffer[5] === 0x74 && // t
    buffer[6] === 0x79 && // y
    buffer[7] === 0x70 // p
  ) {
    const majorBrand = String.fromCharCode(buffer[8], buffer[9], buffer[10], buffer[11])
    if (majorBrand === 'avif' || majorBrand === 'avis' || majorBrand === 'av01') {
      return 'avif'
    }
  }

  return null
}

import { init as initJpegDecode } from '@jsquash/jpeg/decode'
import { init as initPngDecode } from '@jsquash/png/decode'
import { init as initWebpDecode } from '@jsquash/webp/decode'
import { init as initAvifDecode } from '@jsquash/avif/decode'

import JPEG_DEC_WASM from '@jsquash/jpeg/codec/dec/mozjpeg_dec.wasm'
import PNG_WASM from '@jsquash/png/codec/pkg/squoosh_png_bg.wasm'
import WEBP_DEC_WASM from '@jsquash/webp/codec/dec/webp_dec.wasm'
import AVIF_DEC_WASM from '@jsquash/avif/codec/dec/avif_dec.wasm'

let initPromise: Promise<void> | null = null

async function initialiseCodecs() {
  await Promise.all([
    initJpegDecode(JPEG_DEC_WASM),
    initPngDecode(PNG_WASM),
    initWebpDecode(WEBP_DEC_WASM),
    initAvifDecode(AVIF_DEC_WASM)
  ])
}

export const ensureCodecsInitialised = () => {
  if (!initPromise) {
    initPromise = initialiseCodecs()
  }
  return initPromise
}

