export interface DimensionRequest {
  width?: number | null;
  height?: number | null;
}

export interface Dimensions {
  width: number;
  height: number;
}

const round = (value: number) => Math.max(1, Math.round(value));

export function resolveDimensions(
  original: Dimensions,
  request: DimensionRequest,
): Dimensions {
  const requestedWidth = request.width ?? null;
  const requestedHeight = request.height ?? null;

  const hasWidth = typeof requestedWidth === "number" && requestedWidth > 0;
  const hasHeight = typeof requestedHeight === "number" && requestedHeight > 0;

  if (!hasWidth && !hasHeight) {
    throw new Error("Either width or height must be greater than zero.");
  }

  if (hasWidth && hasHeight) {
    return {
      width: round(requestedWidth),
      height: round(requestedHeight),
    };
  }

  const aspect = original.width / original.height;

  if (hasWidth) {
    return {
      width: round(requestedWidth!),
      height: round(requestedWidth! / aspect),
    };
  }

  return {
    width: round(requestedHeight! * aspect),
    height: round(requestedHeight!),
  };
}

import { ensureResizeReady, resize } from "@/lib/codec-init.ts";
import { rgbaToThumbHash } from "thumbhash";

const MAX_THUMB_DIMENSION = 50;

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    const chunk = bytes.subarray(offset, offset + chunkSize);
    binary += String.fromCharCode(...chunk);
  }
  return btoa(binary);
}

async function scaleDown(image: ImageData): Promise<ImageData> {
  if (image.width <= MAX_THUMB_DIMENSION && image.height <= MAX_THUMB_DIMENSION) {
    return image;
  }

  const scale = Math.max(image.width, image.height) / MAX_THUMB_DIMENSION;
  const targetWidth = Math.max(1, Math.round(image.width / scale));
  const targetHeight = Math.max(1, Math.round(image.height / scale));

  await ensureResizeReady();
  return await resize(image, {
    width: targetWidth,
    height: targetHeight,
    fitMethod: "stretch",
    method: "triangle",
  });
}

export async function generateThumbHash(image: ImageData): Promise<string> {
  const source = await scaleDown(image);
  const rgba = new Uint8Array(
    source.data.buffer,
    source.data.byteOffset,
    source.data.byteLength,
  );
  const hash = rgbaToThumbHash(source.width, source.height, rgba);
  return toBase64(hash);
}
